const OUT = 'scalars-quoted';
mkdirSync(OUT, { recursive: true });

// QUOTING NOTE: in the JS source below '\\t' produces the two-character YAML
// *escape sequence* backslash-t inside the case file, while '\t' produces a
// literal TAB byte. Both forms are exercised on purpose. Likewise '\\u0041'
// is the YAML escape and 'A' is the raw character.
const LONGW = 'word '.repeat(24).trim();   // 119 chars, spaces => wrappable
const LONGA = 'a'.repeat(100);             // 100 chars, no break opportunity

const cases = [
  // ------------------------------------------------------------------ //
  // A. double-quoted: every escape sequence in the YAML table, alone
  // ------------------------------------------------------------------ //
  '"\\0"',
  '"\\a"',
  '"\\b"',
  '"\\t"',
  '"\\n"',
  '"\\v"',
  '"\\f"',
  '"\\r"',
  '"\\e"',
  '"\\ "',
  '"\\""',
  '"\\\\"',
  '"\\N"',
  '"\\_"',
  '"\\L"',
  '"\\P"',
  '"\\/"',
  '"\\x41"',
  '"\\u0041"',
  '"\\U00000041"',

  // escapes embedded between ordinary text
  '"a\\tb"',
  '"a\\nb"',

import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const DIR = '/workspace/probe/corpus/block-scalars';
const EXE = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).sort();
let ok = 0,
  err = 0;
const show = new Set(process.argv.slice(2));
for (const f of files) {
  const inp = readFileSync(`${DIR}/${f}`, 'utf8');
  let out, rc;
  try {
    out = execFileSync(EXE, ['--a', inp], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    rc = 0;
    ok++;
  } catch (e) {
    out = (e.stdout || '') + (e.stderr || '');
    rc = e.status;
    err++;
  }
  if (show.size === 0 || show.has(f)) {
    console.log(`##### ${f} rc=${rc}`);
    console.log('  IN : ' + JSON.stringify(inp));
    console.log('  OUT: ' + JSON.stringify(out));
  }
}
console.log(`\ntotal=${files.length} rc0=${ok} rcNonZero=${err}`);

