import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const DIR = '/workspace/probe/corpus/emitter-stress';
const EXE = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).sort();
const show = new Set(process.argv.slice(2));
let ok = 0;
const bad = [];
const stats = { dq: 0, block: 0, plus: 0, ind: 0, explicitKey: 0, wrapped: 0, docEnd: 0 };
for (const f of files) {
  const inp = readFileSync(`${DIR}/${f}`, 'utf8');
  let out, rc;
  try {
    out = execFileSync(EXE, ['--a', inp], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    rc = 0;
    ok++;
  } catch (e) {
    out = (e.stdout || '') + (e.stderr || '');
    rc = e.status;
    bad.push(f);
  }
  if (rc === 0) {
    if (/(^|[\s:-])"/m.test(out)) stats.dq++;
    if (/\|/.test(out)) stats.block++;
    if (/\|\d*\+/.test(out)) stats.plus++;
    if (/\|\d[-+]?/.test(out)) stats.ind++;
    if (/^\? /m.test(out)) stats.explicitKey++;
    if (/\\\n/.test(out)) stats.wrapped++;
    if (/^\.\.\.$/m.test(out)) stats.docEnd++;
  }
  if (show.size === 0 || show.has(f)) {
    console.log(`##### ${f} rc=${rc}`);
    console.log('  IN : ' + JSON.stringify(inp.length > 160 ? inp.slice(0, 160) + '...' : inp));
    console.log('  OUT: ' + JSON.stringify(out.length > 300 ? out.slice(0, 300) + '...' : out));
  }
}
console.log(`\ntotal=${files.length} rc0=${ok} rcNonZero=${bad.length} (${bad.join(',')})`);
console.log('feature coverage:', JSON.stringify(stats));

